import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; 
import './login-page.css'; 
import Header from '../../components/Header/Header'; 
import Footer from '../../components/Footer/Footer'; 

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [userType, setUserType] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const navigate = useNavigate(); 

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    if (!email.trim() || !password.trim() || !userType.trim()) {
      alert('Please fill in all fields.');
      return;
    }

    setIsSubmitting(true);
    try {
      const response = await fetch('http://localhost:5000/login_user', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, userType })
      });

      const data = await response.json();

      if (response.status === 200) {
        alert('Login successful!');

        // Store user details in local storage
        localStorage.setItem('userEmail', data.user);
        localStorage.setItem('rollno', data.rollno);  

        // Redirect based on user type
        navigate(userType === 'admin' ? '/admin' : '/dashboard');
      } else {
        alert(data.error || 'Login failed');
      }
    } catch (error) {
      console.error('Login error:', error);
      alert('An error occurred. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="login-page">
      <Header />
      <div className='login-content'>
        <div className="left-column">
          <img src="/image.jpg" alt="Mock Interview" />
          <h1>Mock Interview</h1>
        </div>
        <hr />
        <div className="right-column">
          <div className="login-container">
            <h2>Login</h2>
            <form onSubmit={handleLogin} className="login-form">
              <div className="form-group">
                <label htmlFor="email">Email</label>
                <input type="email" id="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Enter your email" required />
              </div>
              <div className="form-group">
                <label htmlFor="password">Password</label>
                <input type="password" id="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter your password" required />
              </div>
              <div className="form-group radio-buttons">
                <label>User Type</label>
                <div className="radio-options">
                  <div>
                    <input type="radio" value="admin" checked={userType === 'admin'} onChange={(e) => setUserType(e.target.value)} />
                    <label>Admin</label>
                  </div>
                  <div>
                    <input type="radio" value="student" checked={userType === 'student'} onChange={(e) => setUserType(e.target.value)} />
                    <label>Student</label>
                  </div>
                </div>
              </div>
              <button type="submit" disabled={isSubmitting} className="login-button">
                {isSubmitting ? 'Logging in...' : 'Login'}
              </button>
              <br />
              <br />
              <button type="button" onClick={() => navigate('/sign-up')} className="signup-button">Sign Up</button>
            </form>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default LoginPage;
